// Segundo intento (B): leer con el formato DECLARADO del archivo (español): punto de miles, coma decimal.
// Vacío es dato ausente (null), no cero. Los códigos son texto. Las celdas ambiguas se marcan, no se adivinan.
const esNum = (s) => {
  const t = String(s ?? '').trim();
  if (t === '') return { v: null, aviso: 'vacío' };
  if (/^-?\d+,\d{3}$/.test(t)) return { v: Number(t.replace(',', '.')), aviso: 'ambigua: tres cifras tras la coma (¿' + t.replace(',', '.') + ' o ' + t.replace(',', '') + '?)' };
  if (!/^-?\d{1,3}(\.\d{3})*(,\d+)?$/.test(t) && !/^-?\d+(,\d+)?$/.test(t)) return { v: null, aviso: 'formato no reconocido: ' + t };
  return { v: Number(t.replace(/\./g, '').replace(',', '.')), aviso: null };
};
const pct = (s) => { const t = String(s ?? '').replace('%', '').trim(); return t === '' ? { v: null, aviso: 'vacío' } : { v: Number(t.replace(',', '.')), aviso: null }; };
const fechaIso = (s) => { const m = String(s ?? '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? m[3] + '-' + m[2] + '-' + m[1] : null; };
// Excel (y otros) ponen una marca invisible al principio del archivo (BOM): la primera columna llega como «\ufefffecha».
const sinBom = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k.replace(/^\ufeff/, ''), v]));
const filas = $input.all().map((it) => sinBom(it.json));
const out = [];
for (const r of filas) {
  const u = esNum(r.unidades), p = esNum(r.precio_unitario), d = pct(r.descuento_pct), im = esNum(r.importe);
  const avisos = [];
  if (p.aviso) avisos.push('precio ' + p.aviso); if (d.aviso) avisos.push('descuento ' + d.aviso); if (im.aviso) avisos.push('importe ' + im.aviso); if (u.aviso) avisos.push('unidades ' + u.aviso);
  if (u.v !== null && u.v < 0) avisos.push('devolución (unidades negativas)');
  out.push({ json: { fecha: fechaIso(r.fecha), codigo: String(r.codigo), producto: r.producto, cliente: r.cliente, unidades: u.v, precio_unitario: p.v, descuento_pct: d.v, importe: im.v, estado: avisos.some((a) => /ambigua|no reconocido/.test(a)) ? 'revisar' : (im.v === null ? 'incompleta' : 'ok'), avisos: avisos.join('; ') } });
}
const ok = out.filter((it) => it.json.importe !== null && it.json.estado !== 'revisar');
const total = Math.round(ok.reduce((s, it) => s + it.json.importe, 0) * 100) / 100;
const resumen = { fecha: 'RESUMEN', codigo: '', producto: 'filas: ' + out.length + ' · ok: ' + ok.length + ' · incompletas: ' + out.filter((it) => it.json.estado === 'incompleta').length + ' · revisar: ' + out.filter((it) => it.json.estado === 'revisar').length, cliente: '', unidades: null, precio_unitario: null, descuento_pct: null, importe: total, estado: 'total de las filas ok (sin ambiguas ni vacías)', avisos: '' };
return [...out, { json: resumen }];
